FILES={'model.py': '"""Daily two-factor stochastic-arrival volatility law and price-history-only hedger."""\nimport os,json,time,math\nfrom pathlib import Path\nimport jax\njax.config.update(\'jax_enable_x64\',True)\nimport jax.numpy as jnp\nfrom jax.scipy.special import ndtr,logsumexp\nimport equinox as eqx\nimport numpy as np\nimport optax\nDT=1/252\nHORIZON=126\nBURN=0\nP_HALF={\'easy\':(3.,3.),\'base\':(3.,3.),\'hard\':(40.,3.)}\nQ_HALF={\'easy\':(3.,3.),\'base\':(40.,40.),\'hard\':(1.,40.)}\nPROB={\'easy\':0.,\'base\':1/63,\'hard\':1/63}\nCOSTS=(.0001,.0003,.001)\nLRS=(.0001,.0003,.001)\nBOUNDARIES=(0,60,180,360,600,1200,1800)\n\ndef write(path,value):\n path=Path(path);path.parent.mkdir(parents=True,exist_ok=True)\n tmp=path.with_name(path.name+\'.tmp\');tmp.write_text(json.dumps(value,indent=2,allow_nan=False));os.replace(tmp,path)\n\ndef coefficients(half):\n a=jnp.exp(-jnp.log(2.)/jnp.asarray(half));sd=.35*jnp.sqrt(DT*(1-a*a)/(-2*jnp.log(a)))\n return a,sd\n\ndef variance(x):return jnp.minimum(.04*jnp.exp(jnp.minimum(jnp.sum(x,axis=-1),10.)),1.)\n\ndef advance(x,z,u,half,prob):\n a,sd=coefficients(half)\n return a*x+sd*z+(u<prob)[...,None]*jnp.log(2.)\n\n@eqx.filter_jit\ndef simulate(key,domain,n,measure=\'P\',days=HORIZON,burn=BURN):\n """Return causal normalized price history and latent diagnostic states separately."""\n half=(P_HALF if measure==\'P\' else Q_HALF)[domain]\n kz,ku=jax.random.split(key)\n z=jax.random.normal(kz,(burn+days,n,3));u=jax.random.uniform(ku,(burn+days,n))\n def step(carry,inputs):\n  x,log_s=carry;zz,uu=inputs\n  v=variance(x);r=-.5*v*DT+jnp.sqrt(v*DT)*zz[:,2]\n  return (advance(x,zz[:,:2],uu,half,PROB[domain]),log_s+r),(log_s,x,r)\n (last_x,last_s),(logs,states,returns)=jax.lax.scan(step,(jnp.zeros((n,2)),jnp.zeros(n)),(z,u))\n logs=jnp.concatenate((logs,last_s[None]),axis=0)\n logs=logs-logs[burn][None]\n return {\'logs\':logs,\'states\':jnp.concatenate((states,last_x[None]),axis=0),\'returns\':returns}\n\n@eqx.filter_jit\ndef integrated_variance(key,states,domain,tenor,nq):\n """Future Q jump at end of each interval; no future jump is omitted."""\n kz,ku=jax.random.split(key);z=jax.random.normal(kz,(tenor,nq,2));u=jax.random.uniform(ku,(tenor,nq))\n x=jnp.broadcast_to(states[...,None,:],states.shape[:-1]+(nq,2))\n def step(carry,inputs):\n  x,integ=carry;zz,uu=inputs\n  return (advance(x,zz,uu,Q_HALF[domain],PROB[domain]),integ+variance(x)*DT),None\n (_,integ),_=jax.lax.scan(step,(x,jnp.zeros(x.shape[:-1])),(z,u))\n return integ\n\n@eqx.filter_jit\ndef price(key,states,spot,strike,domain,tenor,nq):\n integ=integrated_variance(key,states,domain,tenor,nq)\n vol=jnp.sqrt(integ);spot=jnp.asarray(spot);strike=jnp.asarray(strike)\n d1=(jnp.log(spot/strike)[...,None]+.5*integ)/vol;d2=d1-vol\n conditional=spot[...,None]*ndtr(d1)-strike[...,None]*ndtr(d2)\n return jnp.mean(conditional,axis=-1)\n\n@eqx.filter_jit\ndef atm_iv(key,states,domain,tenor,nq):\n call=price(key,states,jnp.ones(states.shape[:-1]),jnp.ones(states.shape[:-1]),domain,tenor,nq)\n def bisect(_,bounds):\n  lo,hi=bounds;mid=(lo+hi)/2;value=2*ndtr(.5*mid*jnp.sqrt(tenor*DT))-1\n  return jnp.where(value<call,mid,lo),jnp.where(value<call,hi,mid)\n lo,hi=jax.lax.fori_loop(0,48,bisect,(jnp.zeros_like(call),jnp.ones_like(call)*3))\n return (lo+hi)/2,call\n\nclass Hedger(eqx.Module):\n gru:eqx.nn.GRUCell\n head:eqx.nn.Linear\n def __init__(self,key):\n  a,b=jax.random.split(key);self.gru=eqx.nn.GRUCell(4,32,key=a);self.head=eqx.nn.Linear(32,1,key=b)\n  self.head=eqx.tree_at(lambda m:(m.weight,m.bias),self.head,(jnp.zeros_like(self.head.weight),jnp.zeros_like(self.head.bias)))\n def __call__(self,features,hidden):\n  hidden=self.gru(features,hidden)\n  return jax.nn.sigmoid(self.head(hidden)[0]),hidden\n\n@eqx.filter_jit\ndef rollout(model,logs,cost,rule=\'learned\'):\n """No states, RV or quotes accepted: a structural observation barrier."""\n n=logs.shape[1];h=jnp.zeros((n,32));holding=jnp.zeros(n)\n def warm(hidden,t):\n  features=jnp.stack((logs[t],logs[jnp.maximum(t-1,0)],jnp.ones(n),jnp.zeros(n)),axis=1)\n  _,hidden=jax.vmap(model)(features,hidden)\n  return hidden,None\n h,_=jax.lax.scan(warm,h,jnp.arange(BURN))\n def step(carry,t):\n  hidden,old=carry;lp=logs[BURN+t];prev=logs[jnp.maximum(BURN+t-1,0)];remaining=(HORIZON-t)/HORIZON\n  features=jnp.stack((lp,prev,jnp.full(n,remaining),old),axis=1)\n  proposed,hidden=jax.vmap(model)(features,hidden)\n  if rule==\'bs\':proposed=ndtr((lp+.5*.04*(HORIZON-t)*DT)/(.2*jnp.sqrt((HORIZON-t)*DT)))\n  if rule==\'constant\':proposed=jnp.full(n,model) # not used; constant evaluated separately\n  s=jnp.exp(lp);next_s=jnp.exp(logs[BURN+t+1]);tc=cost*jnp.abs(proposed-old)*s\n  gain=proposed*(next_s-s)\n  return (hidden,proposed),(gain,tc,proposed)\n (_,holding),(gains,costs,holdings)=jax.lax.scan(step,(h,holding),jnp.arange(HORIZON))\n final_s=jnp.exp(logs[-1]);liquidation=cost*holding*final_s\n payoff=jnp.maximum(final_s-1.,0.)\n loss=payoff-jnp.sum(gains,axis=0)+jnp.sum(costs,axis=0)+liquidation\n return dict(loss=loss,gains=gains,costs=jnp.sum(costs,axis=0)+liquidation,holdings=holdings,payoff=payoff,liquidation=liquidation)\n\n@eqx.filter_jit\ndef constant_rollout(logs,cost,holding):\n s=jnp.exp(logs[BURN:]);payoff=jnp.maximum(s[-1]-1,0.)\n costs=cost*holding*(s[0]+s[-1]);loss=payoff-holding*(s[-1]-s[0])+costs\n return dict(loss=loss,costs=costs)\n\ndef risk(x):\n x=np.asarray(x);z=10*x;m=z.max();return float((m+np.log(np.mean(np.exp(z-m))))/10)\n\ndef metrics(x):\n x=np.asarray(x);return dict(entropic=risk(x),cvar95=float(np.sort(x)[int(.95*len(x)):].mean()),sd=float(x.std(ddof=1)),mse=float(np.mean(x*x)),mean=float(x.mean()))\n\n@eqx.filter_jit\ndef update(model,state,key,domain,cost,optimizer):\n key,sub=jax.random.split(key);logs=simulate(sub,domain,256)[\'logs\']\n def objective(m):return (logsumexp(10*rollout(m,logs,cost)[\'loss\'])-jnp.log(256.))/10\n value,grad=eqx.filter_value_and_grad(objective)(model)\n updates,state=optimizer.update(grad,state,eqx.filter(model,eqx.is_inexact_array))\n return eqx.apply_updates(model,updates),state,key,value,optax.global_norm(grad)\n\ndef samples(model,domain,cost,seed,count=2048,rule=\'learned\',archive=None):\n rows=[];tc=[]\n for start in range(0,count,256):\n  logs=simulate(jax.random.fold_in(jax.random.key(seed),start),domain,256)[\'logs\']\n  out=rollout(model,logs,cost,rule);rows.append(np.asarray(out[\'loss\']));tc.append(np.asarray(out[\'costs\']))\n values=np.concatenate(rows)[:count]\n if not np.isfinite(values).all():raise RuntimeError(\'nonfinite loss\')\n if archive:np.savez_compressed(archive,loss=values,cost=np.concatenate(tc)[:count])\n return values\n\ndef save_model(path,model):\n path=Path(path);tmp=path.with_name(path.name+\'.tmp\');eqx.tree_serialise_leaves(tmp,model);os.replace(tmp,path)\n\ndef train(root,arm):\n domain=\'base\' if arm==\'baseline\' else arm;root=Path(root);root.mkdir(parents=True,exist_ok=True)\n model0=Hedger(jax.random.key(20261017))\n for cost in COSTS:\n  out=root/f\'cost-{round(cost*10000)}bp\';out.mkdir(exist_ok=True);trials=[]\n  if (out/\'selection.json\').exists():continue\n  initial=risk(samples(model0,domain,cost,320261017))\n  for lr in LRS:\n   trial=out/f\'lr-{lr:g}\';trial.mkdir(exist_ok=True)\n   model=model0;optimizer=optax.chain(optax.clip_by_global_norm(1.),optax.adam(lr));state=optimizer.init(eqx.filter(model,eqx.is_inexact_array));key=jax.random.key(220261017)\n   active=0.;steps=0;best=initial;best_time=0.;history=[];compile_time=0.\n   checkpoint=trial/\'checkpoint.json\'\n   if checkpoint.exists():\n    saved=json.loads(checkpoint.read_text())\n    model,state,key_data=eqx.tree_deserialise_leaves(trial/saved[\'state_file\'],(model,state,jax.random.key_data(key)))\n    key=jax.random.wrap_key_data(key_data)\n    active=saved[\'active_seconds\'];steps=saved[\'steps\'];best=saved[\'best\'];best_time=saved[\'best_time\'];history=saved[\'history\'];compile_time=saved[\'compile_seconds\']\n    replay=risk(samples(model,domain,cost,320261017))\n    if abs(replay-history[-1][\'entropic\'])>1e-10:raise RuntimeError(\'Resume development replay mismatch\')\n    write(trial/\'resume.json\',dict(step=steps,active_seconds=active,replay_error=abs(replay-history[-1][\'entropic\'])))\n    t=time.monotonic();warm=update(model,state,key,domain,cost,optimizer);jax.block_until_ready(warm[3]);compile_time+=time.monotonic()-t\n   else:\n    save_model(trial/\'best.eqx\',model)\n    t=time.monotonic();model,state,key,value,gn=update(model,state,key,domain,cost,optimizer);jax.block_until_ready(value);compile_time=time.monotonic()-t;steps+=1\n   for boundary in BOUNDARIES[1:]:\n    if history and history[-1][\'active_seconds\']>=boundary:continue\n    with (trial/\'train.jsonl\').open(\'a\') as log:\n     while active<boundary:\n      t=time.monotonic();model,state,key,value,gn=update(model,state,key,domain,cost,optimizer);jax.block_until_ready(value);active+=time.monotonic()-t;steps+=1\n      if not np.isfinite(float(value)) or not np.isfinite(float(gn)):raise RuntimeError(\'nonfinite update\')\n      if steps%10==0:log.write(json.dumps(dict(step=steps,active_seconds=active,loss=float(value),gradient=float(gn)))+\'\\n\');log.flush()\n    score=risk(samples(model,domain,cost,320261017,archive=trial/f\'dev-{boundary}.npz\'))\n    history.append(dict(active_seconds=active,steps=steps,entropic=score))\n    save_model(trial/\'latest.eqx\',model)\n    if score<best:best=score;best_time=active;save_model(trial/\'best.eqx\',model)\n    write(trial/\'progress.json\',dict(history=history,best=best,best_time=best_time,compile_seconds=compile_time,initial=initial,lr=lr))\n    state_file=f\'state-{boundary}.eqx\';save_model(trial/state_file,(model,state,jax.random.key_data(key)))\n    write(checkpoint,dict(state_file=state_file,active_seconds=active,steps=steps,best=best,best_time=best_time,history=history,compile_seconds=compile_time))\n    # Retain the current complete boundary; checkpoint.json is the atomic commit marker.\n    for old in trial.glob(\'state-*.eqx\'):\n     if old.name!=state_file:old.unlink()\n    print(json.dumps(dict(event=\'selection\',arm=arm,cost=cost,lr=lr,**history[-1])),flush=True)\n   trials.append(dict(lr=lr,best=best,best_time=best_time,steps=steps,active_seconds=active,checkpoint=str(trial/\'best.eqx\')))\n   write(out/\'trials.json\',trials)\n  selected=min(trials,key=lambda x:x[\'best\']);(out/\'selected.eqx\').write_bytes(Path(selected[\'checkpoint\']).read_bytes())\n  write(out/\'selection.json\',dict(arm=arm,domain=domain,cost=cost,selected=selected,trials=trials,initial=initial))\n write(root/\'complete.json\',dict(status=\'complete\',arm=arm))\n', 'PROVENANCE.json': '{\n  "diagnostic_sha256": "11cef1d89b0233d3564d58db67d3315f1ae5659d634e5ee6f679cf722000fcbe",\n  "model_sha256": "563e27258baca9af6b2141701d9b4a2919661eed26898fe1c3a541b34b61a8a5",\n  "meaning": "Converged initial Q prices include random future shock arrivals. Accounting constants, never policy observations."\n}', 'initial_premiums.json': '{\n  "easy": 0.05640042269166317,\n  "base": 0.09659917006524685,\n  "hard": 0.072932160822336\n}', 'adaptive.py': '"""Domain-independent persistent-learner entropic curriculum primitives.\n\nNo sampling, IO or hidden target data occurs here. Callers own disjoint streams,\ncheckpointing and historical snapshots. All callbacks must be JAX traceable.\n"""\nfrom typing import NamedTuple\n\nimport equinox as eqx\nimport jax\nimport jax.numpy as jnp\nimport optax\nfrom jax.scipy.special import logsumexp\n\n\nclass Generator(NamedTuple):\n    logits: object\n    opt_state: object\n\n\ndef detached(tree):\n    return jax.tree.map(\n        lambda x: jax.lax.stop_gradient(x) if eqx.is_array(x) else x, tree\n    )\n\n\ndef entropic(losses, gamma=10., weights=None):\n    """Normalized weighted empirical entropic risk (positive weights).\n\n    Differentiating this scalar, including its denominator, is essential for\n    nonlinear DPG. At all-one weights it equals the ordinary learner objective.\n    """\n    if weights is None:\n        return (logsumexp(gamma * losses) - jnp.log(losses.size)) / gamma\n    return (\n        logsumexp(gamma * losses + jnp.log(weights))\n        - jnp.log(jnp.sum(weights))\n    ) / gamma\n\n\ndef probabilities(logits, prior, epsilon=.05):\n    return (1. - epsilon) * jax.nn.softmax(logits) + epsilon * prior\n\n\ndef init_generator(prior, optimizer):\n    """prior must be strictly positive and normalized; baseline is independent."""\n    logits = jnp.log(prior)\n    return Generator(logits, optimizer.init(logits))\n\n\ndef weighted_block(student, batches, weights, losses_fn, optimizer, gamma=10.,\n                   rematerialize=True):\n    """K persistent clipped-Adam updates; weights shape [K,B].\n\n    student=(Equinox model, actual Optax state). losses_fn(model,batch) must\n    return B terminal losses. Optimizer can include clipping; nothing detached\n    inside the block, so DPG differentiates moments and clipping as implemented.\n    """\n    model, opt_state = student\n    params, static = eqx.partition(model, eqx.is_inexact_array)\n\n    def step(carry, inputs):\n        p, state = carry\n        batch, w = inputs\n\n        def objective(candidate):\n            return entropic(losses_fn(eqx.combine(candidate, static), batch), gamma, w)\n\n        value, gradient = jax.value_and_grad(objective)(p)\n        updates, state = optimizer.update(gradient, state, p)\n        return (eqx.apply_updates(p, updates), state), value\n\n    scan_step = jax.checkpoint(step) if rematerialize else step\n    (params, opt_state), values = jax.lax.scan(\n        scan_step, (params, opt_state), (batches, weights)\n    )\n    return (eqx.combine(params, static), opt_state), values\n\n\ndef make_target(losses_fn, hard, easy=None, scales=(1., 1.), gamma=10.):\n    """Hard entropic, or balanced scaled easy/hard entropic objective.\n\n    scales=(easy,hard) fixed positive constants frozen before adaptive training.\n    Hard-only remains unscaled, as original entropic teacher implementation.\n    """\n    def objective(model):\n        h = entropic(losses_fn(model, hard), gamma)\n        if easy is None:\n            return h\n        e = entropic(losses_fn(model, easy), gamma)\n        return .5 * (e / scales[0] + h / scales[1])\n    return objective\n\n\ndef dpg_attributions(student, batches, block_fn, target_fn, weight_shape):\n    """Return actual post-block state and raw negative weight derivatives.\n\n    block_fn(student,batches,weights)->(post_student, learner_values).\n    The incoming state is detached once; every update within K is differentiated.\n    No differentiating the simulator, discrete regime IDs or carried past blocks.\n    """\n    student, batches = detached(student), detached(batches)\n\n    def after(weights):\n        post, values = block_fn(student, batches, weights)\n        return target_fn(post[0]), (post, values)\n\n    (target_after, (post, values)), derivative = eqx.filter_value_and_grad(\n        after, has_aux=True\n    )(jnp.ones(weight_shape))\n    return detached(post), values, detached(-derivative), target_after\n\n\ndef soar_reward(pre_model, post_model, target_fn, baseline, decay=.9):\n    before, after = target_fn(pre_model), target_fn(post_model)\n    improvement = detached(before - after)\n    advantage = detached(improvement - baseline)\n    return advantage, decay * baseline + (1. - decay) * improvement, {\n        \'target_before\': before, \'target_after\': after,\n        \'improvement\': improvement, \'ema_baseline\': baseline,\n    }\n\n\ndef find_adam_state(state):\n    if hasattr(state, \'nu\') and hasattr(state, \'count\'):\n        return state\n    children = state.values() if isinstance(state, dict) else state\n    if isinstance(state, (tuple, list, dict)):\n        for child in children:\n            found = find_adam_state(child)\n            if found is not None:\n                return found\n    return None\n\n\ndef selfplay_rewards(model, historical, opt_state, batches, losses_fn,\n                     learner_lr, outer_round, gamma=10., beta2=.999,\n                     adam_epsilon=1e-8, adam_eps_root=0.):\n    """Entropic-gradient intrinsic reward, one normalization per learner batch.\n\n    historical must be pre-block snapshot floor(outer_round/2). Uses the actual\n    learner Adam bias-corrected second moments. Historical direction is old-new.\n    No target-domain batch or risk score is accepted by this function.\n    """\n    adam = find_adam_state(opt_state)\n    if adam is None:\n        raise ValueError(\'Selfplay requires actual learner Adam second moments\')\n    params, static = eqx.partition(model, eqx.is_inexact_array)\n    historical_leaves = jax.tree.leaves(eqx.filter(historical, eqx.is_inexact_array))\n    current_leaves, parameter_structure = jax.tree.flatten(params)\n    if len(historical_leaves) != len(current_leaves) or any(\n        h.shape != p.shape or h.dtype != p.dtype\n        for h, p in zip(historical_leaves, current_leaves)\n    ):\n        raise ValueError(\'Historical snapshot parameter layout changed\')\n    # Separate pickle loads can reconstruct Equinox\'s private Missing sentinels\n    # with different identities in static metadata. The historical numerical\n    # parameters enter this direction on the frozen current architecture.\n    historical_params = jax.tree.unflatten(parameter_structure, historical_leaves)\n    correction = 1. - beta2 ** jnp.maximum(adam.count, 1)\n    preconditioner = jax.tree.map(\n        lambda v: learner_lr / (jnp.sqrt(v / correction + adam_eps_root) + adam_epsilon), adam.nu\n    )\n    direction = jax.tree.map(\n        lambda h, p, v: (h - p) * v, historical_params, params, preconditioner\n    )\n\n    def one(batch):\n        def values(p):\n            return losses_fn(eqx.combine(p, static), batch)\n        losses, directional = eqx.filter_jvp(values, (params,), (direction,))\n        # B*softmax is the per-example contribution to the directional\n        # derivative of empirical entropic risk, expressed on a mean scale.\n        return jnp.abs(losses.size * jax.nn.softmax(gamma * losses) * directional)\n\n    rewards = jax.vmap(one)(batches)\n    rewards = jnp.where(jnp.asarray(outer_round) > 0, rewards, jnp.zeros_like(rewards))\n    return detached(rewards), {\n        \'parameter_movement_norm\': optax.global_norm(jax.tree.map(\n            lambda h, p: h - p, historical_params, params\n        )),\n        \'historical_index\': jnp.asarray(outer_round) // 2,\n    }\n\n\ndef generator_step(generator, optimizer, ids, rewards, prior, selfplay=False,\n                   epsilon=.05, kl_coefficient=.01, expert_coefficient=1.,\n                   normalization_epsilon=1e-8, apply_update=True):\n    """Summed raw scores for DPG/SOAR; mean PG + normalized EI for selfplay."""\n    ids, rewards = detached(ids), detached(rewards)\n\n    def objective(logits):\n        q = probabilities(logits, prior, epsilon)\n        logp = jnp.log(q)[ids]\n        if selfplay:\n            advantage = (rewards - jnp.mean(rewards)) / (\n                jnp.std(rewards) + normalization_epsilon\n            )\n            policy = -jnp.mean(advantage * logp)\n            expert = -jnp.sum(rewards * logp) / (\n                jnp.sum(rewards) + normalization_epsilon\n            )\n        else:\n            policy = -jnp.sum(rewards * logp)\n            expert = jnp.array(0.)\n        prior_penalty = kl_coefficient * jnp.sum(q * (jnp.log(q) - jnp.log(prior)))\n        return policy + expert_coefficient * expert + prior_penalty, (\n            policy, expert, prior_penalty\n        )\n\n    (loss, (policy, expert, penalty)), grad = jax.value_and_grad(\n        objective, has_aux=True\n    )(generator.logits)\n    updates, state = optimizer.update(grad, generator.opt_state, generator.logits)\n    candidate = Generator(optax.apply_updates(generator.logits, updates), state)\n    result = jax.lax.cond(jnp.asarray(apply_update), lambda: candidate, lambda: generator)\n    q = probabilities(result.logits, prior, epsilon)\n    return result, {\n        \'teacher_loss\': loss, \'policy_loss\': policy,\n        \'expert_iteration_loss\': expert, \'prior_penalty\': penalty,\n        \'teacher_gradient_norm\': optax.global_norm(grad),\n        \'probabilities\': q, \'kl\': jnp.sum(q * (jnp.log(q) - jnp.log(prior))),\n        \'entropy\': -jnp.sum(q * jnp.log(q)),\n        \'reward_mean\': jnp.mean(rewards), \'reward_std\': jnp.std(rewards),\n        \'reward_min\': jnp.min(rewards), \'reward_max\': jnp.max(rewards),\n        \'reward_nonfinite\': jnp.sum(~jnp.isfinite(rewards)),\n        \'generator_update_applied\': jnp.asarray(apply_update),\n    }\n', 'train_adaptive.py': '"""GPU worker training with resumable persistent learner and teacher state."""\nfrom pathlib import Path\nimport gc\nimport hashlib\nimport json\nimport os\nimport pickle\nimport time\n\nimport equinox as eqx\nimport jax\nimport jax.numpy as jnp\nimport numpy as np\nimport optax\n\nfrom adaptive import (detached, dpg_attributions, entropic, generator_step,\n                      init_generator, make_target, probabilities,\n                      selfplay_rewards, soar_reward, weighted_block)\n\n\ndef write(path, value):\n    tmp = path.with_name(path.name + \'.tmp\')\n    tmp.write_text(json.dumps(value, indent=2, allow_nan=False) + \'\\n\')\n    os.replace(tmp, path)\n\n\ndef save(path, payload):\n    tmp = path.with_name(path.name + \'.tmp\')\n    with tmp.open(\'wb\') as stream:\n        pickle.dump(jax.device_get(payload), stream, protocol=5)\n    os.replace(tmp, path)\n\n\ndef load(path):\n    with path.open(\'rb\') as stream:\n        payload = pickle.load(stream)\n    return jax.tree.map(lambda x: jnp.asarray(x) if isinstance(x, np.ndarray) else x,\n                        payload)\n\n\ndef canonical_model(loaded, template):\n    """Restore model values using the current architecture\'s static metadata.\n\n    Pickle can reconstruct distinct Equinox Missing sentinels. Canonicalizing\n    before JIT prevents false static-argument cache misses for every snapshot.\n    """\n    if type(loaded) is not type(template):\n        raise RuntimeError(\'Historical model architecture changed\')\n    leaves = jax.tree.leaves(loaded)\n    expected = jax.tree.leaves(template)\n    if len(leaves) != len(expected) or any(\n        x.shape != y.shape or x.dtype != y.dtype for x, y in zip(leaves, expected)\n    ):\n        raise RuntimeError(\'Historical model parameter layout changed\')\n    return jax.tree.unflatten(jax.tree.structure(template), leaves)\n\n\ndef run(adapter, make_model, output, design, arm, lr):\n    """One predeclared LR trial; callers freeze choices before final evaluation."""\n    if jax.default_backend() != \'gpu\':\n        raise RuntimeError(\'Numerical work requires GPU\')\n    out = Path(output)\n    out.mkdir(parents=True, exist_ok=True)\n    # Pre-block snapshots support exact self-play continuation on the worker.\n    # Keep this growing recovery cache outside incrementally exported outputs;\n    # latest/selected complete checkpoints and all metrics remain exported.\n    history_dir = Path(os.environ.get(\'JOB_SELFPLAY_HISTORY_DIR\',\n                                     str(out.parent.parent / \'selfplay-history\' / arm / f\'lr-{lr:g}\')))\n    history_dir.mkdir(parents=True, exist_ok=True)\n    block_size = design[\'block_size\']\n    batch_size = design[\'batch_size\']\n    gamma = design[\'gamma\']\n    prior = jnp.array(design[\'generator_prior\'])\n    optimizer = optax.chain(optax.clip_by_global_norm(1.),\n                           optax.adam(lr, eps_root=design.get(\'adam_eps_root\', 0.)))\n    teacher_optimizer = optax.adam(design[\'teacher_lr\'])\n    model = make_model(design[\'seed\'])\n    student = (model, optimizer.init(eqx.filter(model, eqx.is_inexact_array)))\n    generator = init_generator(prior, teacher_optimizer)\n    key = jax.random.key(design[\'training_seed\'])\n    baseline = jnp.array(0.)\n    active = 0.\n    outer = 0\n    best = None\n    best_score = float(\'inf\')\n    completed = []\n    compile_seconds = 0.\n    selection_seconds = 0.\n    monitor_seconds = 0.\n    history_bytes = 0\n    intrinsic = arm == \'selfplay\'\n    fixed_domain = {\'baseline\': design[\'domains\'][1], \'easy_reference\': design[\'domains\'][0],\n                    \'hard_reference\': design[\'domains\'][2]}.get(arm)\n    is_dpg = arm.startswith(\'dpg\')\n    mixed = arm.endswith(\'mixed\')\n    domains = design[\'domains\']\n    recovery_marker = Path(os.environ.get(\'JOB_OUTPUT_DIR\', str(out.parent))) / \'recovery-requirements.json\'\n    if intrinsic:\n        write(recovery_marker, dict(external_history_required_until_complete=True,\n              external_history_path=str(history_dir), arm=arm, lr=lr,\n              rule=\'Do not destroy incomplete selfplay worker without its history cache\'))\n    config_hash = hashlib.sha256(json.dumps(dict(design=design, arm=arm, lr=lr),\n                                           sort_keys=True).encode()).hexdigest()\n    latest = out / \'latest.pkl\'\n    if latest.exists():\n        payload = load(latest)\n        if payload[\'config_hash\'] != config_hash:\n            raise RuntimeError(\'Resume configuration changed\')\n        student, generator, baseline = payload[\'student\'], payload[\'generator\'], payload[\'baseline\']\n        key = jax.random.wrap_key_data(payload[\'key_data\'])\n        active, outer = payload[\'active_seconds\'], payload[\'outer_round\']\n        best, best_score, completed = payload[\'best\'], payload[\'best_score\'], payload[\'completed\']\n        compile_seconds = payload[\'compile_seconds\']\n        selection_seconds = payload[\'selection_seconds\']\n        monitor_seconds = payload.get(\'monitor_seconds\', 0.)\n        history_bytes = sum(p.stat().st_size for p in history_dir.glob(\'*.pkl\'))\n        if intrinsic and outer and not (history_dir / f\'{outer // 2:08d}.pkl\').exists():\n            raise RuntimeError(\'Selfplay recovery history missing; do not reset learner\')\n\n    @eqx.filter_jit\n    def draw(k, q, market):\n        if fixed_domain is not None:\n            batches = jax.vmap(lambda sub: market.domain(sub, fixed_domain, batch_size))(\n                jax.random.split(k, block_size))\n            return batches, jnp.full((block_size, batch_size), domains.index(fixed_domain))\n        return market.draw(k, q, block_size, batch_size)\n\n    @eqx.filter_jit\n    def feedback(k, market):\n        hard = market.domain(jax.random.fold_in(k, 2), domains[2], batch_size)\n        easy = market.domain(jax.random.fold_in(k, 0), domains[0], batch_size) if mixed else None\n        return hard, easy\n\n    @eqx.filter_jit\n    def step(s, g, ema, historical, batches, ids, hard, easy, round_index, market):\n        def block(student_state, data, weights):\n            return weighted_block(student_state, data, weights, market.losses,\n                                  optimizer, gamma)\n        if fixed_domain is not None:\n            post, learner_values = block(s, batches, jnp.ones(ids.shape))\n            return detached(post), g, ema, dict(learner_values=learner_values)\n        target = None if intrinsic else make_target(market.losses, hard, easy,\n                                                     tuple(design[\'scales\']), gamma)\n        if is_dpg:\n            post, learner_values, rewards, target_after = dpg_attributions(\n                s, batches, block, target, ids.shape)\n            teacher_metrics = dict(target_after=target_after)\n        else:\n            if intrinsic:\n                rewards, teacher_metrics = selfplay_rewards(\n                    s[0], historical, s[1], batches, market.losses, lr,\n                    round_index, gamma, adam_eps_root=design.get(\'adam_eps_root\', 0.))\n            post, learner_values = block(s, batches, jnp.ones(ids.shape))\n            if not intrinsic:\n                advantage, ema, teacher_metrics = soar_reward(s[0], post[0], target, ema)\n                rewards = jnp.full(ids.shape, advantage)\n        usable = ((round_index > 0) & (teacher_metrics[\'parameter_movement_norm\'] > 0)\n                  if intrinsic else True)\n        g, gm = generator_step(g, teacher_optimizer, ids, rewards, prior,\n                               selfplay=intrinsic, apply_update=usable,\n                               epsilon=design[\'epsilon\'],\n                               kl_coefficient=design[\'kl_coefficient\'])\n        return detached(post), g, ema, dict(learner_values=learner_values,\n                                            **teacher_metrics, **gm)\n\n    @eqx.filter_jit\n    def dev_losses(m, k, domain, market):\n        return market.losses(m, market.domain(k, domain, 128))\n\n    def selection(m, seed=None, count=None):\n        result = {}\n        seed = design[\'selection_seed\'] if seed is None else seed\n        count = design[\'selection_count\'] if count is None else count\n        for index, d in enumerate(domains):\n            rows = []\n            for start in range(0, count, 128):\n                k = jax.random.fold_in(jax.random.key(seed),\n                                       index * 100000 + start)\n                rows.append(np.asarray(dev_losses(m, k, d, adapter)))\n            losses = np.concatenate(rows)\n            if not np.isfinite(losses).all():\n                raise RuntimeError(\'Nonfinite development loss\')\n            result[d] = float(entropic(jnp.asarray(losses), gamma))\n        result[\'balanced\'] = .5 * (result[domains[0]] / design[\'scales\'][0]\n                                    + result[domains[2]] / design[\'scales\'][1])\n        return result\n\n    def checkpoint(boundary_path=None):\n        payload = dict(student=student, generator=generator, baseline=baseline,\n                          key_data=jax.random.key_data(key), active_seconds=active,\n                          outer_round=outer, best=best, best_score=best_score,\n                          completed=completed, compile_seconds=compile_seconds,\n                          selection_seconds=selection_seconds, monitor_seconds=monitor_seconds,\n                          config_hash=config_hash)\n        save(latest, payload)\n        if boundary_path is not None:\n            save(boundary_path, payload)\n        write(out / \'progress.json\', dict(active_seconds=active, outer_round=outer,\n              learner_updates=outer * block_size, training_paths=outer * block_size * batch_size,\n              teacher_feedback_paths=0 if intrinsic or fixed_domain else outer * batch_size * (2 if mixed else 1),\n              probabilities=(np.eye(3)[domains.index(fixed_domain)].tolist() if fixed_domain else\n                             np.asarray(probabilities(generator.logits, prior)).tolist()),\n              completed_boundaries=completed, best_score=best_score if np.isfinite(best_score) else None,\n              config_hash=config_hash))\n\n    # Compile on a disjoint namespace; retain neither update nor consumed RNG.\n    tick = time.monotonic()\n    warm_batches, warm_ids = draw(jax.random.key(110261017), prior, adapter)\n    warm_hard, warm_easy = ((None, None) if intrinsic or fixed_domain else\n                           feedback(jax.random.key(120261017), adapter))\n    warm = step(student, generator, baseline, student[0], warm_batches, warm_ids,\n                warm_hard, warm_easy, jnp.array(1), adapter)\n    jax.block_until_ready(warm)\n    compile_seconds += time.monotonic() - tick\n    del warm, warm_batches\n    gc.collect()\n    if latest.exists():\n        replay = selection(load(out / best)[\'student\'][0]) if best is not None else None\n        if replay is not None and abs(replay[fixed_domain or \'balanced\'] - best_score) > 1e-10:\n            raise RuntimeError(\'Resume development replay mismatch\')\n        write(out / \'resume.json\', dict(active_seconds=active, outer_round=outer,\n                                        replay_error=0. if replay is not None else None))\n    last_save = time.monotonic()\n    for boundary in design[\'checkpoint_active_seconds\']:\n        if boundary in completed:\n            continue\n        with (out / \'training.jsonl\').open(\'a\') as stream:\n            while active < boundary:\n                tick = time.monotonic()\n                key, draw_key = jax.random.split(key)\n                q = probabilities(generator.logits, prior, design[\'epsilon\'])\n                batches, ids = draw(draw_key, q, adapter)\n                hard, easy = ((None, None) if intrinsic or fixed_domain else feedback(\n                    jax.random.fold_in(jax.random.key(design[\'feedback_seed\']), outer), adapter))\n                if intrinsic:\n                    snapshot = history_dir / f\'{outer:08d}.pkl\'\n                    old_size = snapshot.stat().st_size if snapshot.exists() else 0\n                    save(snapshot, student[0])\n                    history_bytes += snapshot.stat().st_size - old_size\n                    if history_bytes > design[\'history_limit_bytes\']:\n                        raise RuntimeError(\'Frozen selfplay history storage bound exceeded\')\n                    historical = canonical_model(\n                        load(history_dir / f\'{outer // 2:08d}.pkl\'), student[0])\n                else:\n                    historical = student[0]\n                student, generator, baseline, logs = step(\n                    student, generator, baseline, historical, batches, ids, hard, easy,\n                    jnp.array(outer), adapter)\n                jax.block_until_ready(logs)\n                active += time.monotonic() - tick\n                outer += 1\n                if not all(np.isfinite(np.asarray(x)).all() for x in jax.tree.leaves(logs)):\n                    raise RuntimeError(\'Nonfinite adaptive update\')\n                record = {k: np.asarray(v).tolist() for k, v in logs.items()}\n                record.update(active_seconds=active, outer_round=outer,\n                              learner_updates=outer * block_size)\n                stream.write(json.dumps(record, allow_nan=False) + \'\\n\')\n                stream.flush()\n                if time.monotonic() - last_save >= 60:\n                    checkpoint()\n                    last_save = time.monotonic()\n        tick = time.monotonic()\n        scores = selection(student[0])\n        selection_seconds += time.monotonic() - tick\n        name = f\'active-{boundary}.pkl\'\n        score = scores[fixed_domain or \'balanced\']\n        if score < best_score:\n            best_score, best = score, name\n        completed.append(boundary)\n        write(out / f\'selection-{boundary}.json\', scores)\n        if design.get(\'monitor_count\', 0):\n            tick = time.monotonic()\n            monitor = selection(student[0], design[\'monitor_seed\'], design[\'monitor_count\'])\n            monitor_seconds += time.monotonic() - tick\n            write(out / f\'monitor-{boundary}.json\', monitor)\n        checkpoint(out / name)\n    write(out / \'selection.json\', dict(arm=arm, lr=lr, checkpoint=best,\n          selection_score=best_score,\n          criterion=fixed_domain or \'fixed balanced scaled easy/hard development\',\n          active_seconds=active, learner_updates=outer * block_size,\n          training_paths=outer * block_size * batch_size,\n          compile_seconds=compile_seconds, selection_seconds=selection_seconds,\n          monitor_seconds=monitor_seconds,\n          config_hash=config_hash, final_test_opened=False))\n    write(out / \'complete.json\', dict(status=\'complete\', final_test_opened=False))\n    if intrinsic:\n        write(recovery_marker, dict(external_history_required_until_complete=False, arm=arm, lr=lr,\n              reason=\'All trial checkpoints and selection durable on worker; pre-block cache disposable\'))\n', 'archive_history.py': '"""Lossless portable selfplay-history archives, executed only on GPU workers."""\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport tarfile\n\n\ndef digest(stream):\n    h = hashlib.sha256()\n    for block in iter(lambda: stream.read(1024 * 1024), b\'\'):\n        h.update(block)\n    return h.hexdigest()\n\n\ndef archive_history(history_dir, destination):\n    """Retain every pre-block snapshot required by earlier full checkpoints."""\n    history_dir, destination = Path(history_dir), Path(destination)\n    files = sorted(history_dir.glob(\'*.pkl\'))\n    if not files:\n        raise RuntimeError(\'Selfplay history cache is missing; cannot declare portable recovery\')\n    inventory = []\n    for path in files:\n        with path.open(\'rb\') as stream:\n            sha = digest(stream)\n        inventory.append(dict(name=path.name, bytes=path.stat().st_size, sha256=sha))\n    destination.parent.mkdir(parents=True, exist_ok=True)\n    temporary = destination.with_name(destination.name + \'.tmp\')\n    with tarfile.open(temporary, \'w:gz\', compresslevel=1) as archive:\n        for path in files:\n            archive.add(path, arcname=path.name, recursive=False)\n    # Verify the complete exported representation, without loading model code.\n    with tarfile.open(temporary, \'r:gz\') as archive:\n        if archive.getnames() != [row[\'name\'] for row in inventory]:\n            raise RuntimeError(\'Historical snapshot archive member mismatch\')\n        for row in inventory:\n            member = archive.getmember(row[\'name\'])\n            with archive.extractfile(member) as stream:\n                actual = digest(stream)\n            if member.size != row[\'bytes\'] or actual != row[\'sha256\']:\n                raise RuntimeError(\'Historical snapshot archive readback mismatch\')\n    os.replace(temporary, destination)\n    with destination.open(\'rb\') as stream:\n        archive_sha = digest(stream)\n    record = dict(archive=destination.name, archive_bytes=destination.stat().st_size,\n                  archive_sha256=archive_sha, snapshot_count=len(files),\n                  source_history_path=str(history_dir), snapshots=inventory,\n                  restore=\'Extract into the corresponding JOB_SELFPLAY_HISTORY_DIR \'\n                          \'before restoring the full model/optimizer/teacher/RNG checkpoint\')\n    manifest = destination.with_name(destination.name + \'.manifest.json\')\n    temporary_manifest = manifest.with_name(manifest.name + \'.tmp\')\n    temporary_manifest.write_text(json.dumps(record, indent=2) + \'\\n\')\n    os.replace(temporary_manifest, manifest)\n    return record\n', 'option_adapter.py': '"""Price-history-only adapter for the frozen stochastic-option benchmark.\n\nImport and execution belong on GPU workers. Domain menu is easy/base/hard.\nThe batch carries causal log-price paths and an external initial-premium ledger\nconstant. Only log prices reach the policy; premium and domain never become\nfeatures. Latent factors stay internal.\n"""\nfrom pathlib import Path\nimport importlib.util\nimport sys\nimport json\nimport jax\nimport jax.numpy as jnp\nimport equinox as eqx\n\nclass OptionAdapter(eqx.Module):\n    model: object = eqx.field(static=True)\n    cost: float\n    decay: object\n    noise: object\n    prob: object\n    premiums: object\n    names=(\'easy\',\'base\',\'hard\')\n    def __init__(self,source,bp):\n        source=Path(source)\n        path=source/\'model.py\' if source.is_dir() else source\n        spec=importlib.util.spec_from_file_location(\'option_benchmark\',path)\n        self.model=importlib.util.module_from_spec(spec);sys.modules[spec.name]=self.model;spec.loader.exec_module(self.model)\n        self.cost=float(bp)/10000\n        values=json.loads((path.parent/\'initial_premiums.json\').read_text())\n        self.premiums=jnp.asarray([values[n] for n in self.names])\n        half=jnp.asarray([self.model.P_HALF[n] for n in self.names])\n        self.decay,self.noise=jax.vmap(self.model.coefficients)(half)\n        self.prob=jnp.asarray([self.model.PROB[n] for n in self.names])\n    def make_model(self,seed=20261017):\n        return self.model.Hedger(jax.random.key(seed))\n    def losses(self,model,batch):\n        return self.model.rollout(model,batch[\'logs\'],self.cost)[\'loss\']-batch[\'initial_premium\']\n    def domain(self,key,domain,count):\n        if isinstance(domain,int):domain=self.names[domain]\n        if domain==\'baseline\':domain=\'base\'\n        index=self.names.index(domain)\n        return {\'logs\':self.model.simulate(key,domain,count)[\'logs\'],\'initial_premium\':jnp.full(count,self.premiums[index])}\n    def draw(self,key,probabilities,block_size=8,batch_size=256):\n        ik,zk,uk=jax.random.split(key,3)\n        block_ids=jax.random.categorical(ik,jnp.log(jnp.asarray(probabilities)),shape=(block_size,batch_size))\n        ids=block_ids.reshape(-1)\n        total=block_size*batch_size\n        z=jax.random.normal(zk,(self.model.HORIZON,total,3))\n        u=jax.random.uniform(uk,(self.model.HORIZON,total))\n        decay=self.decay[ids];noise=self.noise[ids];prob=self.prob[ids]\n        def step(carry,inputs):\n            x,log_s=carry;zz,uu=inputs\n            v=self.model.variance(x)\n            r=-.5*v*self.model.DT+jnp.sqrt(v*self.model.DT)*zz[:,2]\n            next_x=decay*x+noise*zz[:,:2]+(uu<prob)[:,None]*jnp.log(2.)\n            return (next_x,log_s+r),log_s\n        (_,last),logs=jax.lax.scan(step,(jnp.zeros((total,2)),jnp.zeros(total)),(z,u))\n        return {\'logs\':jnp.concatenate((logs,last[None]),axis=0).reshape(self.model.HORIZON+1,block_size,batch_size).transpose(1,0,2),\'initial_premium\':self.premiums[ids].reshape(block_size,batch_size)},block_ids\n    def validate_on_gpu(self,key):\n        """Numerical smoke for mixed law shape, observation discipline and gradients."""\n        if jax.default_backend()!=\'gpu\':raise RuntimeError(\'GPU required\')\n        model=self.make_model();batch,ids=self.draw(key,jnp.asarray([0.,1.,0.]))\n        assert batch[\'logs\'].shape==(8,127,256) and ids.shape==(8,256)\n        first=jax.tree.map(lambda x:x[0],batch)\n        loss=self.losses(model,first)\n        value,gradient=eqx.filter_value_and_grad(lambda m:jnp.mean(self.losses(m,first)))(model)\n        leaves=jax.tree_util.tree_leaves(eqx.filter(gradient,eqx.is_inexact_array))\n        assert bool(jnp.isfinite(loss).all()) and bool(jnp.isfinite(value))\n        assert all(bool(jnp.isfinite(x).all()) for x in leaves)\n        assert bool((ids==1).all())\n        return {\'shape\':list(batch[\'logs\'].shape),\'blocks\':int(ids.size),\'finite_loss_and_gradient\':True,\'price_history_only\':True}\n'}
